def stats_dict(char_id):
    """Vráti atribúty postavy ako slovník {kľúč: hodnota}."""
    vals = STATS.get(char_id)
    if vals is None:
        return {}
    return dict(zip(STAT_KEYS, vals))


def start_vydrz(char_id):
    """Štartovacia Výdrž = hodnota atribútu Výdrž."""
    d = stats_dict(char_id)
    return d.get("vydrz", 10)


