# Cieľový počet BEŽNÝCH rozhodnutí (A/B/C) na deň podľa typu. Detské sa pripočíta (+1).
TARGET_BEZNE = {
    "skusobny": 3, "pokojny": 3, "bezny": 4, "rusny": 6,
    "tazsi_nepriatel": 7, "mini_boss": 8, "hlavny_boss": 9,
}

# Dejovo bohatšie bežné dni s vyšším cieľom (5 bežných namiesto 4), kľúč = číslo dňa.
TARGET_OVERRIDE = {1: 5, 10: 5, 13: 5, 15: 5, 37: 5, 54: 5, 58: 5}


def target_bezne(entry):
    """Cieľový počet bežných rozhodnutí pre deň (rešpektuje override).
    Talianske dni (group velka) majú EXKLUZÍVNE 2× cieľ (dvojnásobná družina)."""
    base = TARGET_OVERRIDE.get(entry["day"], TARGET_BEZNE[day_tier(entry)])
    if entry.get("group") == "velka":
        return base * 2
    return base

# Štítky typov dní pre badge / GM kalendár
KIND_LABEL = {
    "skusobny": "🌱 Skúšobný", "pokojny": "🌿 Pokojný deň", "bezny": "🗺️ Bežný deň",
    "rusny": "⚡ Rušný deň", "tazsi_nepriatel": "🟡 Silnejší nepriateľ",
    "mini_boss": "🟠 Mini-boss", "hlavny_boss": "🔴 Boss",
}


def day_tier(entry):
    """Typ dňa: skusobny / pokojny / bezny / rusny / tazsi_nepriatel / mini_boss / hlavny_boss.

    Boss/mini-boss/ťažší majú prednosť (z míľnika), inak sa berie z DAY_KIND.
    """
    if entry.get("day", 1) < 1:
        return "skusobny"
    m = entry.get("milnik") or {}
    t = m.get("typ")
    if t in TIER_TYPES:
        return t
    return DAY_KIND.get(entry["day"], "bezny")


def _adjust_dc(o, tier):
    """Prepočíta DC možnosti: pôvodné „treba hodiť" + bump podľa tieru, oreže na [MIN, MAX]."""
    bump = DC_BUMP.get(tier)
    if not bump:
        return o["dc"]
    base = stats_dict(o["postava"]).get(o["atribut"], 0) + o.get("bonus", 0)
    need = o["dc"] - base
    need = max(DC_NEED_MIN, min(DC_NEED_MAX, need + bump))
    return base + need


def _rebase_dc(o, tier):
    """EXTRA rozhodnutia: DC = atribút postavy + cieľ podľa tieru (+ malý jitter), orezané."""
    base = stats_dict(o["postava"]).get(o["atribut"], 0) + o.get("bonus", 0)
    jitter = (o["dc"] % 3) - 1                 # -1..+1, aby A/B/C neboli identické
    need = max(DC_NEED_MIN, min(DC_NEED_MAX, EXTRA_TARGET.get(tier, 12) + jitter))
    return base + need


# ── Per-kapitolové škálovanie DC (od 2026-07) ─────────────────────────────
# Súčasné DC v kapitole (SRC = nameraný min–max) sa lineárne premapujú na cieľový
# rozsah (DST), aby najťažšie rozhodnutie sadlo na cieľové max. Rastie s bodmi +
# bossami: I 28 · II 32 · III 38 (boss) · IV 40 · V 44 (boss) · VI 48, Morgrath 52.
# Prológ = auto-úspech. Detské = treba hodiť max 5, väčšinou auto.
CHAPTER_DC_SRC = {0: (6, 9), 1: (21, 32), 2: (22, 35), 3: (19, 40),
                  4: (23, 34), 5: (22, 38), 6: (22, 41)}
CHAPTER_DC_DST = {0: (3, 6), 1: (16, 28), 2: (18, 32), 3: (20, 38),
                  4: (22, 40), 5: (24, 44), 6: (26, 48)}
MORGRATH_FINALE_DS = "2026-08-30"    # Morgrathove finálne rozhodnutia → max DC 52


def _chapter_scale(dc, src, dst):
    """Lineárne premapuje DC zo zdrojového rozsahu na cieľový (per kapitola)."""
    lo, hi = src
    tlo, thi = dst
    if hi <= lo:
        return thi
    frac = (dc - lo) / (hi - lo)
    return max(3, round(tlo + frac * (thi - tlo)))


def _detske_dc(o):
    """Detské: treba hodiť max 5, väčšinou auto-úspech (need ≤ 0)."""
    base = stats_dict(o["postava"]).get(o["atribut"], 0) + o.get("bonus", 0)
    need = min(5, o["dc"] - 11)          # detské dc 10–12 → need -1..1, väčšinou ≤ 0
    return max(1, base + need)


def _norm_option(o, tier=None, rebase=False, scale=None, detske=False, auto=False):
    ak = o["atribut"]
    p = PARTY_ALL.get(o["postava"], {"meno": o["postava"], "icon": "❔"})
    if detske:
        dc = _detske_dc(o)
    elif auto:                            # prológ — auto-úspech (need ≤ 0)
        base = stats_dict(o["postava"]).get(ak, 0) + o.get("bonus", 0)
        dc = max(3, base - 3)
    else:
        if rebase and tier in EXTRA_TARGET:
            dc = _rebase_dc(o, tier)
        elif tier:
            dc = _adjust_dc(o, tier)
        else:
            dc = o["dc"]
        if scale:
            dc = _chapter_scale(dc, scale[0], scale[1])
    return {
        "label": o["label"],
        "postava_id": o["postava"],
        "postava_nazov": p["meno"],
        "postava_ikona": p["icon"],
        "atribut_key": ak,
        "atribut_nazov": STAT_NAMES[STAT_KEYS.index(ak)] if ak in STAT_KEYS else ak,
        "bonus": o.get("bonus", 0),
        "dc": dc,
        "result_success": o["result_success"],
        "result_near": o["result_near"],
        "result_fail": o["result_fail"],
    }


def _norm_option_d(o, tier=None, base_dcs=None):
    """Skrytá možnosť D — podporuje normalizovaný aj raw formát.

    DC: skrytá cesta má byť o 2 nižšie než NAJĽAHŠIA bežná možnosť rozhodnutia
    (miernou výhodou, nie okamžitým úspechom). Ak base_dcs nie je, fallback na
    tier úpravu / raw DC.
    """
    if not o:
        return None
    pid = o.get("postava_id") or o.get("postava")
    ak = o.get("atribut_key") or o.get("atribut")
    p = PARTY_ALL.get(pid, {"meno": pid, "icon": "❔"})
    bonus = o.get("bonus")
    if bonus is None:
        bonus = sum(b.get("hodnota", 0) for b in o.get("bonusy", []))
    if base_dcs:
        m = min(base_dcs)
        # skrytá cesta: väčšinou o 2 nižšie, občas o 1 (deterministicky ~2/3 : 1/3)
        znizenie = 1 if m % 3 == 0 else 2
        dc = max(3, m - znizenie)
    elif tier and "postava" in o and "atribut" in o:
        dc = _adjust_dc({"postava": pid, "atribut": ak, "bonus": bonus, "dc": o["dc"]}, tier)
    else:
        dc = o.get("dc", 15)
    return {
        "label": o.get("label", "D) Skrytá možnosť"),
        "postava_id": pid, "postava_nazov": p["meno"], "postava_ikona": p["icon"],
        "atribut_key": ak,
        "atribut_nazov": STAT_NAMES[STAT_KEYS.index(ak)] if ak in STAT_KEYS else ak,
        "bonus": bonus, "dc": dc,
        "result_success": o["result_success"],
        "result_near": o.get("result_near", o["result_success"]),
        "result_fail": o.get("result_fail", "Skrytá cesta zlyhala."),
    }


def shop_for_day(ds, entry):
    """Vráti (market_dict, polozky) pre daný deň, alebo (None, [])."""
    market = None
    polozky = []
    mk = MARKET_DAYS.get(ds)
    if mk and mk in MARKETS:
        market = {"nazov": MARKETS[mk]["nazov"], "ikona": MARKETS[mk]["ikona"], "popis": MARKETS[mk]["popis"]}
        polozky = [dict(p) for p in MARKETS[mk]["polozky"]]
    # pridaj prípadné "kupit" položky z items_day
    extra = []
    for it in entry.get("items_day", []):
        if it.get("kde") == "kupit":
            extra.append({
                "nazov": it["nazov"], "ikona": "🛒",
                "vyhoda": it.get("vyhody", ""), "nevyhoda": it.get("nevyhody", ""),
                "cena": it.get("cena", 0), "jednorazovy": it.get("jednorazovy", False),
            })
    if extra and market is None:
        market = {"nazov": "Obchod dňa", "ikona": "🛒", "popis": "Dnešná ponuka na kúpu."}
    polozky = polozky + extra
    if market is None:
        return None, []
    return market, polozky


def detske_for_day(ds):
    """Detské rozhodnutie (vždy posledné) — deterministicky vybrané z DETSKE_POOL."""
    tpl = DETSKE_POOL[_stable_idx(ds, len(DETSKE_POOL))]
    return {
        "id": "detske",
        "typ": "detske",
        "prompt": tpl["prompt"],
        "options": [_norm_option(o, detske=True) for o in tpl["options"]],
    }


# =========================================================================
#  EXTRA ROZHODNUTIA pre ťažších nepriateľov / mini-bossov / bossov
#  (boss +3, mini-boss +2, ťažší +1). DC sú už finálne (bez ďalšieho bumpu).
# =========================================================================
def _xo(label, postava, atribut, dc, succ, near, fail, bonus=0):
    return {"label": label, "postava": postava, "atribut": atribut, "bonus": bonus, "dc": dc,
            "result_success": succ, "result_near": near, "result_fail": fail}


def _xd(prompt, typ, *opts, option_d=None):
    d = {"prompt": prompt, "type": typ, "options": list(opts)}
    if option_d is not None:
        d["option_d"] = option_d
    return d


