# Legendárne predmety s aktívnym tlačidlom, ktoré ostávajú v inventári aj po vyčerpaní
# nábojov (trvalý pasívny efekt) — kľúč = podreťazec názvu (malými písmenami).
LEGENDARY_ACTIVE = ("plášť hviezd", "zbroj prvého strážcu", "luk hviezdneho vetra")


def _consumable_for(nazov):
    """Vráti (pouzitie, pocet_pouziti) pre spotrebný predmet podľa názvu, alebo (None, None)."""
    low = (nazov or "").lower()
    for kw, eff in CONSUMABLE_EFFECTS.items():
        if kw in low:
            return eff["pouzitie"], eff["pocet_pouziti"]
    return None, None


def normalize_item(raw):
    """Zjednotí nájdený/kúpený/legendárny predmet na objekt s efektmi (mod).

    Kedy bonus platí: zbraň (názov/text) → kladné bonusy „boj", postihy „stále";
    ostatné predmety → „stále". Dá sa prebiť poľom „kedy" v dátach.
    Spotrebné predmety (medovník, jedlo, lektvary…) dostanú `pouzitie` + `pocet_pouziti`.
    """
    if raw is None:
        return None
    vyh = raw.get("vyhody") or raw.get("vyhoda") or ""
    nev = raw.get("nevyhody") or raw.get("nevyhoda") or ""
    mods = raw.get("mod")
    if mods is None:
        blob = (raw.get("nazov", "") + " " + vyh + " " + nev).lower()
        is_weapon = any(h in blob for h in _BOJ_HINTS)
        explicit = raw.get("kedy")
        mods = []
        for m in parse_mods(vyh) + parse_mods(nev):
            if explicit:
                m["kedy"] = explicit
            elif is_weapon and m["hodnota"] > 0:
                m["kedy"] = "boj"
            else:
                m["kedy"] = "vzdy"
            mods.append(m)
    nazov = raw.get("nazov", "?")
    pouzitie = raw.get("pouzitie")
    pocet = raw.get("pocet_pouziti")
    if pouzitie is None:                       # doplň efekt spotrebného predmetu podľa názvu
        auto_p, auto_n = _consumable_for(nazov)
        if auto_p is not None:
            pouzitie = auto_p
            if pocet in (None, 0):
                pocet = auto_n
    return {
        "nazov": nazov,
        "ikona": raw.get("ikona", ""),
        "vyhody": vyh, "nevyhody": nev,
        "pre_koho": raw.get("pre_koho", "vsetci"),
        "mod": mods,
        "zahada": raw.get("zahada"),
        "jednorazovy": raw.get("jednorazovy", False),
        "cena": raw.get("cena", 0),
        "pouzitie": pouzitie,
        "pocet_pouziti": pocet,
        "trvaly": raw.get("trvaly", any(k in nazov.lower() for k in LEGENDARY_ACTIVE)),
    }


def item_allowed_for(item, cid):
    """Smie daná postava niesť tento predmet (pole pre_koho)?"""
    pk = item.get("pre_koho", "vsetci") if isinstance(item, dict) else "vsetci"
    if pk in (None, "vsetci", "vsetky", "any", ""):
        return True
    if isinstance(pk, str):
        return cid == pk
    return cid in pk


