def build_decisions(ds, entry):
    """Jednotný zoznam rozhodnutí dňa.

    Poradie: bežné (decision1/2/3) → extra (boss/mini-boss/ťažší + Taliansko) → detské
    → 🎁 predmet → 🛒 nákup. Každý deň má min. 4 rozhodnutia (3 bežné + detské),
    ťažšie dni viac; talianske dni (velka) majú EXKLUZÍVNE 2× (viac hráčov).
    """
    out = []
    tier = day_tier(entry)
    # per-kapitolové škálovanie DC (prológ = auto; Morgrath finále → 52)
    chapter = entry.get("chapter", 1)
    auto = (chapter == 0)
    src = CHAPTER_DC_SRC.get(chapter)
    dst = CHAPTER_DC_DST.get(chapter)
    if ds == MORGRATH_FINALE_DS and dst:
        dst = (dst[0], 53)               # kompenzuje zaokrúhlenie → najťažšie sadne na 52
    scale = (src, dst) if (src and dst and not auto) else None
    for i in (1, 2, 3):
        d = entry.get(f"decision{i}")
        if not d:
            continue
        opts_norm = [_norm_option(o, tier, scale=scale, auto=auto) for o in d["options"]]
        out.append({
            "id": f"d{i}",
            "typ": d.get("type", "fyzicke"),
            "prompt": d["prompt"],
            "options": opts_norm,
            "option_d": _norm_option_d(d.get("option_d"), tier, [o["dc"] for o in opts_norm]),
        })
    # 🤝 tímové scény (len bossovia / mini-bossovia) — spojené atribúty, jedna kocka.
    # Renderujú sa POČAS boja (po base, pred extra), aby neprišli až po porazení bossa.
    # Výnimka: Morgrathovo finále — tam je tímová scéna vyvrcholenie, ostáva NA KONCI.
    team_out = []
    for ti, td in enumerate(TEAM_DECISIONS.get(ds, []), 1):
        contribs = []
        for c, a in td["contribs"]:
            p = PARTY_ALL.get(c, {"meno": c, "icon": "❔"})
            contribs.append({"postava_id": c, "atribut_key": a,
                             "postava_nazov": p["meno"], "postava_ikona": p["icon"],
                             "atr_start": stats_dict(c).get(a, 0)})
        dc = sum(x["atr_start"] for x in contribs) + td["need"]
        team_out.append({
            "id": f"tim{ti}", "typ": "timova", "prompt": td["prompt"],
            "contribs": contribs, "dc": dc,
            "result_success": td["result_success"],
            "result_near": td["result_near"],
            "result_fail": td["result_fail"],
            "finale": td.get("finale", False),
        })
    finale = (ds == MORGRATH_FINALE_DS)
    if not finale:
        out.extend(team_out)                 # tímové scény počas boja
    # extra rozhodnutia pre ťažšie dni (DC odvodené od atribútu postavy podľa tieru)
    xi = 4
    for d in (EXTRA_DECISIONS.get(ds, []) + EXTRA_DECISIONS_VI.get(ds, [])
              + EXTRA_DECISIONS_5.get(ds, []) + EXTRA_DECISIONS_TALIANSKO.get(ds, [])):
        opts_norm = [_norm_option(o, tier, rebase=True, scale=scale, auto=auto) for o in d["options"]]
        out.append({
            "id": f"d{xi}",
            "typ": d.get("type", "fyzicke"),
            "prompt": d["prompt"],
            "options": opts_norm,
            "option_d": _norm_option_d(d.get("option_d"), tier, [o["dc"] for o in opts_norm]),
        })
        xi += 1
    if finale:
        out.extend(team_out)                 # finále — tímová scéna ako vyvrcholenie na konci
    # detské — posledné z rozhodnutí (pred predmetom a nákupom); DC sa NEzvyšuje (pre najmenších)
    out.append(detske_for_day(ds))
    # nájdené predmety -> predmetové rozhodnutia
    pi = 0
    for it in entry.get("items_day", []):
        if it.get("kde", "najst") in ("najst", "nájsť"):
            out.append({"id": f"predmet{pi}", "typ": "predmet", "predmet": it})
            pi += 1
    # nákup (trh)
    market, polozky = shop_for_day(ds, entry)
    if market:
        out.append({"id": "nakup", "typ": "nakup", "market": market, "polozky": polozky})
    return out


# === KONIEC DÁT ===
